BAD = {'stored': [], 'layout': []}

def render(v, layout):
    sign = ''
    if int(layout[0]) == 1:
        sign = '-'
    return sign + str(abs(v)).zfill(int(layout[1]))

def forward(groups):
    if len(groups) != 2:
        return BAD
    neg, digits = groups
    n = 0
    v = int(digits)
    if neg == '-':
        n = 1
        v = 0 - v
    layout = [n, len(digits)]
    if render(v, layout) != neg + digits:
        return BAD
    return {'stored': [v], 'layout': layout}

def inverse(record):
    return render(int(record['stored'][0]), record.get('layout', []))

